struct OwnerDelta {int id,owner;};
__global__ void packPeerState(const Car* c,int n,const Road* roads,const Movement* moves,const int* jo,const int* owners,int rank,int epoch,int phase,StateMessage* out,int* counts,int cap,OwnerDelta* changes){
 int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n||owners[i]!=rank)return;
 int owner=authority(c[i],roads,moves,jo),ghost=c[i].state==1?jo[roads[c[i].edges[c[i].k]].from]:owner;
 if(owner!=rank){int k=atomicAdd(counts+owner,1);if(k<cap)out[owner*cap+k]={i,rank,owner,owner,epoch,phase,payload(c[i])};int d=atomicAdd(counts+3,1);if(d<n)changes[d]={i,owner};}
 if(ghost!=owner){int k=atomicAdd(counts+ghost,1);if(k<cap)out[ghost*cap+k]={i,rank,ghost,owner,epoch,phase,payload(c[i])};}
}
__global__ void applyOwners(int* owners,const OwnerDelta* changes,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)owners[changes[i].id]=changes[i].owner;}
struct Workers {
 std::mutex mutex;std::condition_variable start,done;int generation=0,finished=0;bool stop=false;std::function<void(int)> fn;std::exception_ptr failure;std::vector<std::thread> threads;
 Workers(){for(int r=0;r<3;++r)threads.emplace_back([this,r]{int seen=0;for(;;){std::function<void(int)> work;{std::unique_lock<std::mutex> l(mutex);start.wait(l,[&]{return stop||generation!=seen;});if(stop)return;seen=generation;work=fn;}try{work(r);}catch(...){std::lock_guard<std::mutex> l(mutex);failure=std::current_exception();}{std::lock_guard<std::mutex> l(mutex);++finished;done.notify_one();}}});}
 void run(std::function<void(int)> work){{std::lock_guard<std::mutex> l(mutex);fn=work;finished=0;failure=nullptr;++generation;}start.notify_all();std::unique_lock<std::mutex> l(mutex);done.wait(l,[&]{return finished==3;});if(failure)std::rethrow_exception(failure);}
 ~Workers(){{std::lock_guard<std::mutex> l(mutex);stop=true;}start.notify_all();for(auto& t:threads)t.join();}
};
struct PeerPool {
 StateMessage *send,*receive;OwnerDelta *changes,*incomingChanges;int *counts,*hostCounts;ReservationMessage *resSend,*resReceive;int* keys;int resCount[3]={0,0,0},resOffset[3]={0,0,0};int cap,n,nr;
 PeerPool(Partition* p,const Model& m,const std::vector<int>& jo):cap(p->messageCap),n(p->n),nr(p->nr){p->select();check(cudaMalloc(&send,3ULL*cap*sizeof(StateMessage)));check(cudaMalloc(&receive,3ULL*cap*sizeof(StateMessage)));check(cudaMalloc(&changes,n*sizeof(OwnerDelta)));check(cudaMalloc(&incomingChanges,3ULL*n*sizeof(OwnerDelta)));check(cudaMalloc(&counts,4*sizeof(int)));check(cudaMallocHost(&hostCounts,4*sizeof(int)));check(cudaMalloc(&resSend,nr*8*sizeof(ReservationMessage)));check(cudaMalloc(&resReceive,3ULL*nr*8*sizeof(ReservationMessage)));
 std::vector<int> list;for(int d=0;d<3;++d){resOffset[d]=list.size();for(int r=0;r<nr;++r)if(jo[m.roads[r].from]==p->rank&&jo[m.roads[r].to]==d&&d!=p->rank)for(int l=0;l<m.roads[r].lanes;++l){list.push_back(r*8+l);++resCount[d];}}keys=device(list.empty()?std::vector<int>{0}:list);
 }
};
struct PeerTransport {
 std::vector<Partition*>& p;Workers& workers;std::vector<PeerPool*> pools;unsigned long long bytes=0,messages=0,migrations=0,reservations=0,controlBytes=0;int peak=0;
 PeerTransport(std::vector<Partition*>& parts,Workers& w,const Model& m,const std::vector<int>& jo):p(parts),workers(w){for(auto* part:p)pools.push_back(new PeerPool(part,m,jo));for(auto* dst:p){dst->select();for(auto* src:p)if(src->gpu!=dst->gpu){int access=0;check(cudaDeviceCanAccessPeer(&access,dst->gpu,src->gpu));if(!access)throw std::runtime_error("Peer access required");auto e=cudaDeviceEnablePeerAccess(src->gpu,0);if(e==cudaErrorPeerAccessAlreadyEnabled)cudaGetLastError();else check(e);}}}
 void exchange(int epoch,int phase){
 workers.run([&](int r){auto* a=p[r];auto* b=pools[r];a->select();check(cudaMemsetAsync(b->counts,0,16));packPeerState<<<(a->n+127)/128,128>>>(a->b,a->n,a->roads,a->moves,a->jo,a->owners,r,epoch,phase,b->send,b->counts,b->cap,b->changes);check(cudaMemcpyAsync(b->hostCounts,b->counts,16,cudaMemcpyDeviceToHost));check(cudaDeviceSynchronize());});
 for(int s=0;s<3;++s){auto* b=pools[s];if(b->hostCounts[3]>b->n||(phase&&b->hostCounts[3]))throw std::runtime_error("Invalid migration phase/capacity");migrations+=b->hostCounts[3];controlBytes+=2ULL*b->hostCounts[3]*sizeof(OwnerDelta);for(int d=0;d<3;++d){int count=b->hostCounts[d];if(count>b->cap)throw std::runtime_error("Peer message capacity exceeded");messages+=count;if(s!=d)bytes+=count*sizeof(StateMessage);peak=std::max(peak,count);}}
 workers.run([&](int d){auto* dst=p[d];auto* b=pools[d];dst->select();for(int s=0;s<3;++s){auto* a=pools[s];int count=a->hostCounts[d],changed=a->hostCounts[3];if(count)check(cudaMemcpyPeerAsync(b->receive+s*b->cap,dst->gpu,a->send+d*a->cap,p[s]->gpu,count*sizeof(StateMessage)));if(changed)check(cudaMemcpyPeerAsync(b->incomingChanges+s*b->n,dst->gpu,a->changes,p[s]->gpu,changed*sizeof(OwnerDelta)));}check(cudaDeviceSynchronize());});
 workers.run([&](int d){auto* a=p[d];auto* b=pools[d];a->select();for(int s=0;s<3;++s){int count=pools[s]->hostCounts[3];if(count)applyOwners<<<(count+127)/128,128>>>(a->owners,b->incomingChanges+s*b->n,count);}clearGhosts<<<(a->n+127)/128,128>>>(a->b,a->n,a->owners,d);for(int s=0;s<3;++s){int count=pools[s]->hostCounts[d];if(count)unpackState<<<(count+127)/128,128>>>(a->b,b->receive+s*b->cap,count);}check(cudaDeviceSynchronize());});
 }
 void reservationExchange(int epoch){workers.run([&](int r){auto* a=p[r];auto* b=pools[r];a->select();int count=b->resCount[0]+b->resCount[1]+b->resCount[2];if(count)packReservations<<<(count+127)/128,128>>>(a->ds,b->keys,a->roads,a->jo,count,r,epoch,b->resSend);check(cudaDeviceSynchronize());});
 for(int s=0;s<3;++s)for(int d=0;d<3;++d){int c=pools[s]->resCount[d];reservations+=c;bytes+=c*sizeof(ReservationMessage);}
 workers.run([&](int d){auto* b=pools[d];p[d]->select();for(int s=0;s<3;++s){auto* a=pools[s];int count=a->resCount[d];if(count){check(cudaMemcpyPeerAsync(b->resReceive+s*b->nr*8,p[d]->gpu,a->resSend+a->resOffset[d],p[s]->gpu,count*sizeof(ReservationMessage)));unpackReservations<<<(count+127)/128,128>>>(p[d]->ds,b->resReceive+s*b->nr*8,count);}}check(cudaDeviceSynchronize());});
 }
};
static double ms(std::chrono::steady_clock::time_point a,std::chrono::steady_clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
int main(int argc,char** argv){try{
 if(argc<10)throw std::runtime_error("concurrent MODEL SNAPSHOT OWNERS STEPS OUT single|peer verify instrument repeat [profile-step=-1]");
 setenv("LPSIM_MOTION_CONTEXT","3",1);Model model(argv[1]);std::ifstream f(argv[2],std::ios::binary);int n;float start;f.read((char*)&n,4);f.read((char*)&start,4);if(n<1)throw std::runtime_error("Invalid n");std::vector<Car> cars(n);f.read((char*)cars.data(),n*sizeof(Car));if(!f)throw std::runtime_error("Invalid snapshot");std::ifstream map(argv[3]);std::vector<int> jo(model.nj);for(int& j:jo)if(!(map>>j)||j<0||j>2)throw std::runtime_error("Invalid ownership");
 int steps=std::stoi(argv[4]);std::string out=argv[5],backend=argv[6];bool peer=backend=="peer",verify=std::stoi(argv[7]),instrument=std::stoi(argv[8]);int repeat=std::stoi(argv[9]),profileStep=argc>10?std::stoi(argv[10]):-1;std::vector<int> owners(n);for(int i=0;i<n;++i)owners[i]=authority(cars[i],model.roads.data(),model.moves.data(),jo.data());
 auto setupBegin=std::chrono::steady_clock::now();Workers workers;std::vector<Partition*> parts;for(int r=0;r<(peer?3:1);++r)parts.push_back(new Partition(peer?r:-1,std::getenv("LPSIM_LOGICAL")?0:r,model,cars,owners,jo,false,2*n));std::unique_ptr<PeerTransport> transport;if(peer)transport.reset(new PeerTransport(parts,workers,model,jo));std::unique_ptr<Partition> reference;if(verify&&peer)reference.reset(new Partition(-1,0,model,cars,owners,jo,false,2*n));
 std::ofstream memory(out+"/memory.csv");memory<<"rank,device,free_bytes,total_bytes,vehicle_slots,car_arrays_bytes,compact_state_bytes,peer_state_pool_bytes,owner_delta_pool_bytes,reservation_pool_bytes\n";for(auto* p:parts){p->select();size_t free,total;check(cudaMemGetInfo(&free,&total));memory<<p->rank<<','<<p->gpu<<','<<free<<','<<total<<','<<n<<','<<2ULL*n*sizeof(Car)<<','<<14ULL*n*sizeof(float)<<','<<(peer?6ULL*p->messageCap*sizeof(StateMessage):0)<<','<<(peer?4ULL*n*sizeof(OwnerDelta):0)<<','<<(peer?4ULL*model.nr*8*sizeof(ReservationMessage):0)<<'\n';}
 double setupMs=ms(setupBegin,std::chrono::steady_clock::now());std::ofstream series(out+"/steps.csv");series<<"step,time,total_ms,motion_ms,exchange0_ms,junction_ms,reservation_ms,spawn_ms,exchange1_ms,gpu0_motion_ms,gpu1_motion_ms,gpu2_motion_ms,gpu0_junction_ms,gpu1_junction_ms,gpu2_junction_ms,state_messages,reservation_messages,migrations,wire_bytes,control_bytes\n";
 std::ofstream populations(out+"/populations.csv");populations<<"step,time,rank,pending,stopped,moving,connector,completed,ghosts,allocated_slots,requests,admissions,denied_space,denied_conflict_or_yield\n";std::vector<Car> observed(n);double total=0,verifyMs=0;cudaEvent_t ev[3][2];for(auto* p:parts){p->select();check(cudaEventCreate(&ev[p->rank<0?0:p->rank][0]));check(cudaEventCreate(&ev[p->rank<0?0:p->rank][1]));}
 for(int step=0;step<steps;++step){float t=start+step*.25f;bool prof=step==profileStep;if(prof){for(auto* p:parts){p->select();cudaProfilerStart();}}
 unsigned long long om=transport?transport->messages:0,orr=transport?transport->reservations:0,ob=transport?transport->bytes:0,oc=transport?transport->controlBytes:0,ot=transport?transport->migrations:0;double gmotion[3]={0,0,0},gjunction[3]={0,0,0};
 auto stage=[&](std::function<void(Partition*)> fn,double* gpu){auto work=[&](int r){auto* p=parts[r];p->select();if(instrument)check(cudaEventRecord(ev[r][0]));fn(p);if(instrument)check(cudaEventRecord(ev[r][1]));if(peer||instrument)check(cudaDeviceSynchronize());if(instrument&&gpu){float elapsed;check(cudaEventElapsedTime(&elapsed,ev[r][0],ev[r][1]));gpu[r]=elapsed;}};if(peer)workers.run(work);else work(0);};
 auto a=std::chrono::steady_clock::now();stage([&](Partition* p){p->motion(t,.25f,0);},gmotion);auto b=std::chrono::steady_clock::now();if(peer)transport->exchange(step,0);auto c=std::chrono::steady_clock::now();stage([&](Partition* p){p->junction(t,0);},gjunction);auto d=std::chrono::steady_clock::now();if(peer)transport->reservationExchange(step);auto e=std::chrono::steady_clock::now();stage([&](Partition* p){p->spawn();},nullptr);auto h=std::chrono::steady_clock::now();if(peer)transport->exchange(step,1);else {parts[0]->select();check(cudaDeviceSynchronize());}auto z=std::chrono::steady_clock::now();double elapsed=ms(a,z);total+=elapsed;
 if(prof){for(auto* p:parts){p->select();cudaProfilerStop();}}
 series<<step<<','<<t+.25f<<','<<elapsed<<','<<ms(a,b)<<','<<ms(b,c)<<','<<ms(c,d)<<','<<ms(d,e)<<','<<ms(e,h)<<','<<ms(h,z);for(double x:gmotion)series<<','<<x;for(double x:gjunction)series<<','<<x;series<<','<<(transport?transport->messages-om:0)<<','<<(transport?transport->reservations-orr:0)<<','<<(transport?transport->migrations-ot:0)<<','<<(transport?transport->bytes-ob:0)<<','<<(transport?transport->controlBytes-oc:0)<<'\n';
 // Diagnostics are separate from unprofiled timing repetitions.
 if(verify||instrument||step==steps-1){for(auto* p:parts)p->inspect();if(peer){parts[0]->select();check(cudaMemcpy(owners.data(),parts[0]->owners,n*sizeof(int),cudaMemcpyDeviceToHost));}for(int i=0;i<n;++i)observed[i]=parts[peer?owners[i]:0]->inspection[i];
 if(instrument||step==steps-1){for(int r=0;r<(peer?3:1);++r){int pop[6]={0,0,0,0,0,0};for(int i=0;i<n;++i){auto v=observed[i];if(!peer||owners[i]==r){if(v.state==0)pop[0]++;else if(v.state==1)pop[v.v<.5f?1:2]++;else if(v.state==2)pop[3]++;else if(v.state==3)pop[4]++;}else if(parts[r]->inspection[i].state!=-1)pop[5]++;}int req=0,admit=0,space=0,conflict=0;if(instrument){parts[r]->select();std::vector<EntryRequest> qs(n);check(cudaMemcpy(qs.data(),parts[r]->requests,n*sizeof(EntryRequest),cudaMemcpyDeviceToHost));for(int i=0;i<n;++i)if(!peer||owners[i]==r){req+=qs[i].pass>=0;admit+=observed[i].event==1||observed[i].event==2;space+=observed[i].denial==2;conflict+=observed[i].denial==1||observed[i].denial==3;}}populations<<step<<','<<t+.25f<<','<<r;for(int k:pop)populations<<','<<k;populations<<','<<n<<','<<req<<','<<admit<<','<<space<<','<<conflict<<'\n';}}
 if(verify){if(peer){reference->motion(t,.25f,0);reference->junction(t,0);reference->spawn();reference->inspect();for(int i=0;i<n;++i)if(std::memcmp(&observed[i],&reference->inspection[i],sizeof(Car)))throw std::runtime_error("Exact mismatch step="+std::to_string(step)+" vehicle="+std::to_string(i));for(int r=0;r<3;++r)for(int i=0;i<n;++i){auto v=observed[i];bool visible=owners[i]==r||(v.state==1&&jo[model.roads[v.edges[v.k]].from]==r);if(visible){if(std::memcmp(&v,&parts[r]->inspection[i],sizeof(Car)))throw std::runtime_error("Ghost mismatch");}else if(parts[r]->inspection[i].state!=-1)throw std::runtime_error("Stale ghost");}std::swap(reference->a,reference->b);}validatePhysical(observed,model);}
 }
 if(instrument&&!peer&&(int(t+.25f)==30||int(t+.25f)==180||int(t+.25f)==360||int(t+.25f)==540||int(t+.25f)==600)&&((step+1)%4==0)){float stamp=t+.25f;std::ofstream snap(out+"/snapshot_"+std::to_string(int(stamp))+".bin",std::ios::binary);snap.write((char*)&n,4);snap.write((char*)&stamp,4);snap.write((char*)observed.data(),n*sizeof(Car));}
 verifyMs+=ms(z,std::chrono::steady_clock::now());for(auto* p:parts)std::swap(p->a,p->b);
 }
 std::ofstream final(out+"/final.bin",std::ios::binary);float end=start+steps*.25f;final.write((char*)&n,4);final.write((char*)&end,4);final.write((char*)observed.data(),n*sizeof(Car));
 std::ofstream metrics(out+"/metrics.json");metrics<<"{\"backend\":\""<<backend<<"\",\"steps\":"<<steps<<",\"requested\":"<<n<<",\"repeat\":"<<repeat<<",\"verified_every_step\":"<<(verify?"true":"false")<<",\"instrumented\":"<<(instrument?"true":"false")<<",\"compute_wall_ms\":"<<total<<",\"setup_ms\":"<<setupMs<<",\"diagnostics_and_serialization_ms\":"<<verifyMs<<",\"state_messages\":"<<(transport?transport->messages:0)<<",\"wire_bytes\":"<<(transport?transport->bytes:0)<<",\"control_bytes\":"<<(transport?transport->controlBytes:0)<<",\"ownership_transfers\":"<<(transport?transport->migrations:0)<<"}\n";
 std::cout<<"PASS backend="<<backend<<" steps="<<steps<<" verify="<<verify<<" compute_ms="<<total<<std::endl;return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
